  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_2 : Integer;
    attribute accumulatedMs : Integer := 0;
    attribute displayValue : Integer := 0;
    attribute previousPressed : Boolean := false;
    perform action tick {
      first start;
      then if io_0 and (not previousPressed) {
        first start;
        then assign accumulatedMs := 0;
        then assign displayValue := 0;
      } else {
        first start;
        then assign accumulatedMs := accumulatedMs + io_2;
        then if accumulatedMs >= 1000 {
          first start;
          then assign accumulatedMs := accumulatedMs - 1000;
          then assign displayValue := displayValue + 1;
        }
      }
      then assign previousPressed := io_0;
    }
    out attribute io_1 : Integer = displayValue;
  }
  part system : Controller;
}
